import { test, expect } from '@playwright/test';

test.describe('Table Row Numbers - First Column', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should display row numbers in the first column when enabled', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify row numbers are visible in the first column
    const rowNumbers = page.getByText(/row \d+/);
    await expect(rowNumbers).toBeVisible();

    // Verify row numbers are correctly ordered
    const firstRowNumber = page.getByText('row 1');
    const secondRowNumber = page.getByText('row 2');
    const thirdRowNumber = page.getByText('row 3');
    await expect(firstRowNumber).toBeVisible();
    await expect(secondRowNumber).toBeVisible();
    await expect(thirdRowNumber).toBeVisible();

    // Verify row numbers are clickable and navigate to the corresponding row
    await expect(firstRowNumber).toBeVisible();
    await expect(firstRowNumber).toHaveAttribute('data-testid', 'row-number-1');
    await expect(firstRowNumber).toBeClickable();
    await firstRowNumber.click();
    await expect(page).toHaveURL(/table\.php\?page=1/);

    await expect(secondRowNumber).toBeVisible();
    await expect(secondRowNumber).toHaveAttribute('data-testid', 'row-number-2');
    await expect(secondRowNumber).toBeClickable();
    await secondRowNumber.click();
    await expect(page).toHaveURL(/table\.php\?page=1&row=2/);

    await expect(thirdRowNumber).toBeVisible();
    await expect(thirdRowNumber).toHaveAttribute('data-testid', 'row-number-3');
    await expect(thirdRowNumber).toBeClickable();
    await thirdRowNumber.click();
    await expect(page).toHaveURL(/table\.php\?page=1&row=3/);
  });

  test('should not display row numbers when disabled', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify row numbers are not visible
    const rowNumbers = page.getByText(/row \d+/);
    await expect(rowNumbers).not.toBeVisible();

    // Verify row numbers are not clickable
    const firstRowNumber = page.getByText('row 1');
    await expect(firstRowNumber).not.toBeClickable();

    // Verify table rows are still accessible
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    const secondRow = page.getByRole('row', { name: /row 2/i });
    await expect(secondRow).toBeVisible();

    const thirdRow = page.getByRole('row', { name: /row 3/i });
    await expect(thirdRow).toBeVisible();

    // Verify table headers are still visible
    const firstHeader = page.getByRole('columnheader', { name: /Name/i });
    await expect(firstHeader).toBeVisible();

    const secondHeader = page.getByRole('columnheader', { name: /Age/i });
    await expect(secondHeader).toBeVisible();

    const thirdHeader = page.getByRole('columnheader', { name: /Email/i });
    await expect(thirdHeader).toBeVisible();
  });
});
